Connection conn = null;
PreparedStatement studentStmt = null;
PreparedStatement courseStmt = null;

try {
    // Load and register driver
    Class.forName("oracle.jdbc.driver.OracleDriver");

    // Create and get connection
    conn = DriverManager.getConnection("jdbc:oracle:thin:Mark/passwd@kecmachine:1521:edford");

    // Start transaction
    conn.setAutoCommit(false);

    // Insert into student table
    studentStmt = conn.prepareStatement("INSERT INTO Student VALUES (?, ?, ?, ?)");
    studentStmt.setInt(1, 1001);
    studentStmt.setString(2, "John");
    studentStmt.setString(3, "Mysore");
    studentStmt.setLong(4, 9213456780L);
    studentStmt.executeUpdate();

    // Insert into course table
    courseStmt = conn.prepareStatement("INSERT INTO Course VALUES (?, ?, ?)");
    courseStmt.setInt(1, 201);
    courseStmt.setString(2, "Java Programming");
    courseStmt.setInt(3, 1001); // foreign key to student_id
    courseStmt.executeUpdate();

    // Commit if both succeed
    conn.commit();
    System.out.println("Student and course inserted successfully");

} catch (Exception e) {
    // Rollback if any error occurs
    if (conn != null) {
        try {
            conn.rollback();
            System.out.println("Transaction rolled back due to an error");
        } catch (SQLException rollbackEx) {
            rollbackEx.printStackTrace();
        }
    }
    e.printStackTrace();
} finally {
    // Clean up
    try {
        if (studentStmt != null) studentStmt.close();
        if (courseStmt != null) courseStmt.close();
        if (conn != null) conn.close();
    } catch (SQLException se) {
        se.printStackTrace();
    }
}

